mapper.sql:
SELECT DISTINCT IIF (BPADDRESS.CTY_0 = '', 'OTHERS', BPADDRESS.CTY_0) AS CityCode, BPADDRESS.CTY_0 AS CityName FROM EXPLOIT.BPADDRESS BPADDRESS WHERE 1 = 1
AND ( UPPER(BPADDRESS.CTY_0) = UPPER(#{City}) OR UPPER(BPADDRESS.CTY_0) LIKE UPPER('%' + #{City} + '%') )
AND BPADDRESS.CRY_0 = #{CountryCode}
